use rig::prelude::*;
use rig::providers::openai::{self, OpenAI};


let client = OpenAI::from_env()?;


// A completion model, used to build an agent...
let agent = AgentBuilder::new(client.completion(openai::GPT_5_5))
    .preamble("You are Gandalf the White, discussing the fate of Middle Earth.")
    .build();


// ...and an embedding model, for embeddings and vector search.
let embedder = client.embedding(openai::TEXT_EMBEDDING_3_SMALL, None);
